// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {IArgusTaxToken} from "./interfaces/IArgusTaxToken.sol";
import {IArgusTaxProcessor} from "./interfaces/IArgusTaxProcessor.sol";
import {IArgusDividendTracker} from "./interfaces/IArgusDividendTracker.sol";
import {IUniswapV3Pool} from "./interfaces/IUniswapV3.sol";
import {ArgusUnits} from "./libraries/ArgusUnits.sol";
import {TickMath} from "./libraries/TickMath.sol";
import {TaxConfig, ArgusConstants, ArgusErrors} from "./types/ArgusTypes.sol";

/// @notice The one tracker entry point that lives outside {IArgusDividendTracker}.
/// @dev The tracker discovers `mainPool` lazily, by staticcalling back into the
///      token from inside `setShare`. That discovery is the single most expensive
///      share update there is, and it lands on whichever unlucky trade happens to
///      be first. `syncPool()` is permissionless and idempotent, so the token
///      fires it the moment it knows the pool and retires the path. Declared here
///      rather than imported because it is an extension the tracker offers, not
///      part of the contract the token is written against - every call to it is
///      best-effort.
interface IArgusDividendTrackerSync {
    function syncPool() external;
}

/// @notice Everything {ArgusTaxToken-initialize} needs. The Portal builds this.
struct InitParams {
    string name;
    string symbol;
    /// @dev The artwork, surfaced on-chain by {ArgusTaxToken-logo}. May be empty.
    ///      The Portal passes its `TokenMeta.imageURI` straight through; see the
    ///      note on {ArgusTaxToken-logo} for why this one string is stored when the
    ///      other three socials are not.
    string logoURI;
    uint256 totalSupply;
    /// @dev Where the whole supply is minted - the Portal, which sells it down
    ///      the curve and then seeds the graduation LP.
    address supplyRecipient;
    /// @dev The creator. May only ever call `reduceTaxes` and `renounce`; pass
    ///      the zero address to launch already-renounced.
    address owner;
    address portal;
    address taxProcessor;
    /// @dev May be zero only when `config.dividendBps == 0`.
    address dividendTracker;
    /// @dev Addresses the launch flow needs untaxed that the token cannot work
    ///      out for itself - the graduation LP executor and the LP locker. Fixed
    ///      forever here: there is deliberately no setter, so an exemption can
    ///      never be handed out, or revoked, after launch.
    address[] extraExempt;
    TaxConfig config;
}

/// @title ArgusTaxToken
/// @notice A creator-configured tax token that trades on a Uniswap v3 pool.
///
/// @dev Extends OpenZeppelin's {ERC20} DIRECTLY, and that is load-bearing. An
///      earlier token in this codebase (`HigherToken`) inserted itself into a
///      three-deep inheritance chain and its `_update` override became a silent
///      no-op, because `super._update` resolved to the sibling base rather than
///      to ERC20. Nothing reverted; the tax simply never moved. One base, one
///      unambiguous `super`.
///
///      Nothing here is `immutable`. This is an EIP-1167 clone target, and an
///      `immutable` is baked into the IMPLEMENTATION's runtime code, so every
///      clone would silently read the implementation's value - the same tax
///      rate, the same creator wallet, on every launch. All config lives in
///      storage, written once by {initialize}.
///
///      ONE KNOWN AND DELIBERATE DEPARTURE FROM ERC-20, stated here because an
///      integrator reads the contract header and not the middle of `_update`.
///      A sell debits the seller MORE than the amount passed to
///      `transferFrom`:
///
///          transferFrom(from, pool, value)  moves  value * (1 + sellTaxBps/1e4)
///          out of `from`, while spending allowance for `value` only.
///
///      The direction is the surprising part. An ordinary fee-on-transfer token
///      debits `value` and delivers less; this one delivers exactly `value`,
///      because a v3 pool re-reads its own balance and reverts if short by a
///      wei, and takes the tax as a surcharge from what the seller has left.
///      Approve `value * (1 + sellTaxBps/1e4)`, and do not infer the transferred
///      amount from a balance delta.
///
///      Charging the allowance for the surcharge would close the gap and would
///      make an exact-allowance sell revert, which is the honeypot signature the
///      surcharge exists to avoid. The gap is documented rather than moved. See
///      the note at the sell branch in {_update} for the full argument, and
///      audit finding M-1, 2026-09-03.
contract ArgusTaxToken is ERC20, ReentrancyGuard, IArgusTaxToken {
    using ArgusUnits for uint256;

    uint256 private constant Q96 = 1 << 96;

    /// @dev Gas ceiling on each {IArgusDividendTracker-setShare}. Sized against the
    ///      real implementation's measured cost, not a guess: 2.5k on the
    ///      unchanged-share early-out, ~52k median, ~69k for a first-time holder
    ///      (three cold SSTOREs plus the one-off staticcall to {mainPool}), and a
    ///      ~113k one-time path where the tracker first LEARNS the pool address
    ///      and has to un-count a share it had already credited to it. Worst case
    ///      those combine, so the cap has to clear ~182k.
    ///
    ///      Undersizing this is SILENT and permanent: the try/catch swallows the
    ///      out-of-gas, the trade succeeds, and that holder's share is simply
    ///      never recorded - they earn nothing and `totalShares` is wrong from
    ///      then on. {_syncPool} exists to retire the 113k path at launch so the
    ///      combined worst case never actually occurs.
    uint256 private constant SHARE_SYNC_GAS = 200_000;

    // - storage (all of it; see the contract-level note on `immutable`) --

    string private _tokenName;
    string private _tokenSymbol;
    string private _logoURI;

    TaxConfig private _config;

    /// @notice The creator. May only ever call {reduceTaxes} and {renounce}.
    address public owner;

    /// @notice The Argus Portal: launches the token, runs the bonding curve, and
    ///         performs the graduation LP mint. Tax-exempt.
    address public portal;

    address public taxProcessor;
    address public dividendTracker;

    /// @notice The v3 pool this token taxes against. Registered by the Portal at
    ///         LAUNCH (the address is CREATE2-deterministic), long before
    ///         {graduate} flips trading on, so the pre-graduation block below has
    ///         something real to block.
    address public mainPool;

    /// @dev Cached from `pool.token0()` at registration. `swapBack()` needs to
    ///      know which side of the pair it is selling before it can pick a swap
    ///      direction, a price bound, or read the callback deltas the right way
    ///      round.
    bool public tokenIsToken0;

    /// @notice False while the token is on the bonding curve. Token-level tax
    ///         only runs after this flips; before it, the Portal charges the tax
    ///         in native at trade time.
    bool public graduated;

    bool private _initialized;

    /// @notice `launchedAt + taxDuration`, or 0 when the tax is permanent. Can
    ///         never be re-armed or extended.
    uint256 public taxExpiry;
    uint256 public launchedAt;

    /// @notice Dust guard under the quote-value trigger, in tokens. Fixed at
    ///         launch; see {ArgusConstants-MIN_SWAPBACK_SUPPLY_DIVISOR} for why it is
    ///         set far below anything that can bind honestly.
    uint256 public minSwapBackTokens;

    mapping(address account => bool) public isExempt;

    /// @dev Set immediately before `pool.swap()` and cleared immediately after,
    ///      exactly as {PotatoCurvePad} does it. Outside that window every
    ///      callback is rejected, so the callback cannot be used to make this
    ///      contract pay out its own balance.
    address internal _expectedPoolCallback;

    // - events beyond the interface --

    /// @dev Emitted instead of reverting when the tracker misbehaves. See
    ///      {_trySetShare}: a revert here would revert the trade.
    event ShareSyncFailed(address indexed user);

    /// @dev The processor refused the follow-on {IArgusTaxProcessor-dispatch}. The
    ///      swap-back itself still succeeded; the buckets are simply still
    ///      sitting in the processor waiting for someone to call it.
    event DispatchFailed();
    event OwnershipRenounced(address indexed previousOwner);
    event Graduated(address indexed pool);

    /// @dev Locks the implementation itself. A clone gets fresh storage and
    ///      initializes normally; the implementation can never be initialized,
    ///      so nobody can take ownership of the address the clones point at.
    constructor() ERC20("", "") {
        _initialized = true;
    }

    // - initialization --

    /// @notice One-shot setup, called by the factory in the same transaction as
    ///         `Clones.clone()`.
    /// @dev Bundled into a struct rather than taken as eleven arguments because
    ///      the flat form is stack-too-deep on 0.8.24 without via-IR, in the
    ///      compiler's own ABI decoder.
    function initialize(InitParams calldata p) external {
        if (_initialized) revert ArgusErrors.AlreadyInitialized();
        _initialized = true;

        TaxConfig calldata cfg = p.config;
        if (cfg.buyTaxBps > ArgusConstants.MAX_TAX_BPS || cfg.sellTaxBps > ArgusConstants.MAX_TAX_BPS) {
            revert ArgusErrors.TaxTooHigh();
        }
        if (cfg.buyTaxBps + cfg.sellTaxBps == 0) revert ArgusErrors.ZeroTaxNotAllowed();
        if (uint256(cfg.creatorBps) + cfg.burnBps + cfg.dividendBps != ArgusConstants.BPS) {
            revert ArgusErrors.AllocationMustSumTo10000();
        }
        if (cfg.creatorBps > 0 && cfg.creatorWallet == address(0)) {
            revert ArgusErrors.CreatorWalletRequired();
        }
        if (
            p.portal == address(0) || p.taxProcessor == address(0) || p.supplyRecipient == address(0)
                || p.totalSupply == 0
        ) {
            revert ArgusErrors.ZeroAddress();
        }
        // A tracker is optional only when nothing would ever be sent to it.
        if (cfg.dividendBps > 0 && p.dividendTracker == address(0)) revert ArgusErrors.ZeroAddress();

        _tokenName = p.name;
        _tokenSymbol = p.symbol;
        _logoURI = p.logoURI;
        _config = cfg;
        owner = p.owner;
        portal = p.portal;
        taxProcessor = p.taxProcessor;
        dividendTracker = p.dividendTracker;

        launchedAt = block.timestamp;
        if (cfg.taxDuration != 0) taxExpiry = block.timestamp + cfg.taxDuration;

        // The trigger itself is a dollar figure and lives in ArgusConstants. Only
        // the dust guard is supply-relative, so only it needs resolving here.
        minSwapBackTokens = p.totalSupply / ArgusConstants.MIN_SWAPBACK_SUPPLY_DIVISOR;

        isExempt[address(this)] = true;
        isExempt[p.portal] = true;
        isExempt[p.taxProcessor] = true;
        if (p.dividendTracker != address(0)) isExempt[p.dividendTracker] = true;
        isExempt[ArgusConstants.DEAD] = true;
        isExempt[address(0)] = true;
        for (uint256 i; i < p.extraExempt.length; ++i) {
            isExempt[p.extraExempt[i]] = true;
        }

        _mint(p.supplyRecipient, p.totalSupply);
    }

    // - portal-only wiring --

    /// @notice Register the canonical v3 pool. Called at LAUNCH, not graduation.
    ///
    /// @dev Registering early is the whole point: a v3 pool address is
    ///      CREATE2-deterministic from (factory, token0, token1, fee), so the
    ///      Portal knows it the moment the clone exists, and knowing it is what
    ///      lets {_update} block anyone from seeding that pool at a rigged price
    ///      ahead of graduation.
    ///
    ///      Honest limitation: this blocks THE pool, not every conceivable pool.
    ///      A rogue pool at a different fee tier is undetectable on-chain - a
    ///      pool is just an address. The canonical pool is the one that matters,
    ///      because it is the one graduation seeds and the one aggregators route
    ///      to.
    function setMainPool(address pool) external {
        if (msg.sender != portal) revert ArgusErrors.OnlyPortal();
        if (mainPool != address(0)) revert ArgusErrors.PoolAlreadySet();
        if (pool == address(0)) revert ArgusErrors.ZeroAddress();

        address t0 = IUniswapV3Pool(pool).token0();
        address t1 = IUniswapV3Pool(pool).token1();
        // The quote leg must be Arc's native-USDC view, because that is what the
        // 6dp -> 18dp conversion in `swapBack()` assumes. A pool against
        // anything else would silently mis-scale every proceeds figure by 1e12.
        bool zeroIsThis = t0 == address(this) && t1 == ArgusUnits.USDC;
        bool oneIsThis = t1 == address(this) && t0 == ArgusUnits.USDC;
        if (!zeroIsThis && !oneIsThis) revert ArgusErrors.ZeroAddress();

        mainPool = pool;
        tokenIsToken0 = zeroIsThis;
        emit MainPoolSet(pool);

        _syncPool();
    }

    /// @notice Flip on post-graduation behaviour: token-level tax, DEX trading,
    ///         and {swapBack}.
    /// @dev Separate from {setMainPool} so the pre-graduation pool block has a
    ///      registered pool to enforce against for the whole curve phase.
    function graduate() external {
        if (msg.sender != portal) revert ArgusErrors.OnlyPortal();
        if (mainPool == address(0)) revert ArgusErrors.PoolNotSet();
        graduated = true;

        emit Graduated(mainPool);

        // Again here, and deliberately: at {setMainPool} the tracker clone may
        // not have been initialized yet, and this call must land BEFORE the
        // graduation LP mint moves the first tokens.
        _syncPool();
    }

    /// @dev Best-effort: retires the tracker's expensive lazy pool discovery.
    ///      Swallowing a failure is the point - the tracker falls back to
    ///      discovering the pool itself, and a launch must never fail because an
    ///      optional optimisation on a collaborator contract did.
    function _syncPool() private {
        address tracker = dividendTracker;
        if (tracker == address(0)) return;
        try IArgusDividendTrackerSync(tracker).syncPool() {} catch {}
    }

    // - ERC20 metadata (clone storage, not constructor storage) --

    /// @dev ERC20's `_name`/`_symbol` are written by ITS constructor, which never
    ///      runs for a clone - a clone would report the implementation's empty
    ///      strings. These read our own storage instead.
    function name() public view override returns (string memory) {
        return _tokenName;
    }

    function symbol() public view override returns (string memory) {
        return _tokenSymbol;
    }

    /// @notice The token's artwork, as a URI. Empty when the creator supplied none.
    ///
    /// @dev THE NAME IS THE FEATURE. `logo()` is selector `0xfb7f21eb`, and that
    ///      is the first thing block explorers, wallets and our own token index
    ///      (`tools/arc-tokens.mjs`, which probes `logo()`, then `tokenURI()`,
    ///      then `metadataURI()`) staticcall when they want art for an Arc token.
    ///      A token that only emits its image in a launch event is discoverable
    ///      by exactly one indexer - ours, and only because we wrote it. Renaming
    ///      this getter makes the token render as a blank monogram everywhere.
    ///
    ///      No setter, deliberately, like everything else fixed at launch here.
    ///      Art that can be swapped after the fact is a rug vector: a token can
    ///      be sold under one image and re-skinned into another once it holds a
    ///      market. What the launch event says and what the getter says can
    ///      therefore never diverge.
    ///
    ///      There is no `tokenURI()` alongside this. See {ArgusPortal-TokenMeta}.
    function logo() external view returns (string memory) {
        return _logoURI;
    }

    // - transfers --

    /// @dev The single ERC20 mutation hook in OZ v5: `_mint`, `_burn`, `transfer`
    ///      and `transferFrom` all land here.
    function _update(address from, address to, uint256 value) internal override {
        if (isExempt[from] || isExempt[to]) {
            // Mint, burn, the graduation LP mint, and every hop between our own
            // contracts. Checked FIRST so the pre-graduation pool block below
            // cannot stop the Portal from seeding the pool at graduation.
            super._update(from, to, value);
        } else if (!graduated) {
            // Phase A: the Portal charges tax in native on the curve, so no
            // token-level tax runs. Only wallet-to-wallet moves are allowed -
            // nobody gets to open a market before graduation does.
            if (from == mainPool || to == mainPool) revert ArgusErrors.PreGraduationPoolTransfer();
            super._update(from, to, value);
        } else {
            (uint16 buyTaxBps, uint16 sellTaxBps) = currentTaxes();

            if (from == mainPool) {
                // BUY. The pool transfers OUT, so skimming here never touches the
                // pool's input-side balance check. Safe with SwapRouter,
                // Universal Router, and every aggregator.
                uint256 taxTokens = (value * buyTaxBps) / ArgusConstants.BPS;
                if (taxTokens != 0) {
                    super._update(from, address(this), taxTokens);
                    super._update(from, to, value - taxTokens);
                } else {
                    super._update(from, to, value);
                }
            } else if (to == mainPool) {
                // SELL (and third-party LP adds, which are indistinguishable and
                // deliberately not special-cased).
                //
                // The pool MUST receive the full `value`: v3 verifies payment by
                // re-reading its own balance inside the swap callback and reverts
                // if it is short by a single wei. Skimming on the way in makes
                // every sell revert - a literal honeypot. So the tax is a
                // SURCHARGE taken from what the seller has left afterwards.
                //
                // The consequence is unavoidable, not a bug: a max-sell pays ZERO
                // sell tax. Proof - let B be the seller's balance and A the amount
                // sold. The pool must receive exactly A, so the total debit is
                // A + A·t. If A == B then A + A·t > B for any t > 0, so either the
                // surcharge is clamped to 0 or the transfer reverts. Reverting on
                // max-sell was explicitly rejected: it is the exact signature
                // honeypot scanners flag, and it would make the token unsellable
                // in the eyes of every terminal. Zero-tax max-sells are the price
                // of being a real, sellable token on v3.
                //
                // The same clamp fires for ANY payer whose balance equals the
                // amount being sold - notably a router that takes custody of the
                // input before paying the pool. See the report notes.
                // THE SURCHARGE IS NOT CHARGED AGAINST THE ALLOWANCE, AND ANY
                // INTEGRATOR HAS TO KNOW THAT. Audit finding M-1, 2026-09-03.
                //
                // The second `_update` below moves tokens out of `from` without
                // passing through `_spendAllowance`, which OZ's `transferFrom`
                // ran once, for `value`, before ever reaching this function. So:
                //
                //     transferFrom(from, to, value) debits `from` by value·(1+t)
                //
                // The unusual half is the DIRECTION. An ordinary fee-on-transfer
                // token debits exactly `value` and DELIVERS LESS than `value`.
                // This one delivers exactly `value` - it has to, the pool counts
                // it - and debits MORE. Anybody who reasons "fee-on-transfer, so
                // the recipient gets less" has it backwards here, and anybody who
                // computes `balanceBefore - balanceAfter` and expects `value`
                // gets a number larger than the one they approved.
                //
                // Two concrete breakages, both real rather than theoretical:
                // a contract that approves exactly `value` and then asserts its
                // own post-balance, and an aggregator that sizes an approval to
                // the trade. Approve `value * (1 + sellTaxBps/10000)`, or approve
                // more.
                //
                // FIXING IT IN THE OBVIOUS WAY WAS CONSIDERED AND REJECTED.
                // Spending the allowance for the surcharge as well would make the
                // token conformant and would make an exact-allowance sell REVERT,
                // which is the same honeypot signature the surcharge design
                // exists to avoid - traded from one place to another, not
                // removed. A token that reverts a normal-approval sell is
                // unsellable in the eyes of every scanner and terminal, whatever
                // the spec says about it. So the conformance gap is documented
                // rather than closed, and this comment is that documentation.
                super._update(from, to, value);

                uint256 surchargeTokens = (value * sellTaxBps) / ArgusConstants.BPS;
                uint256 remaining = balanceOf(from);
                if (surchargeTokens > remaining) surchargeTokens = remaining;
                if (surchargeTokens != 0) super._update(from, address(this), surchargeTokens);
            } else {
                // Wallet to wallet: never taxed.
                super._update(from, to, value);
            }
        }

        // Anti-snipe - a max-wallet cap for the blocks right after graduation -
        // was considered and deliberately declined. Its absence is a decision,
        // not an oversight; do not re-add it without one. The tradeoff it leaves
        // standing: nothing here prevents a single wallet taking a large share of
        // supply in the opening blocks.

        // NO swap-back here. Ever. On v3 this code runs INSIDE `pool.swap()`
        // with the pool's own reentrancy lock held, so swapping through that pool
        // from here always reverts. Swap-back is its own transaction.
        _syncShares(from, to);
    }

    /// @dev Push both sides' post-transfer balances to the dividend tracker.
    ///      Pools and exempt addresses are skipped: they earn nothing, so telling
    ///      the tracker about them is pure gas.
    function _syncShares(address from, address to) private {
        address tracker = dividendTracker;
        if (tracker == address(0)) return;
        if (!isExempt[from] && from != mainPool) _trySetShare(tracker, from);
        if (!isExempt[to] && to != mainPool) _trySetShare(tracker, to);
    }

    /// @dev try/catch plus a gas cap, and both halves matter.
    ///
    ///      This call happens inside `pool.swap()` on every buy and every sell.
    ///      If the tracker reverts - a bug, an unbounded loop, an out-of-gas -
    ///      an unguarded call would revert the trade, and a token whose trades
    ///      revert is a honeypot no matter how honest the intent. The tracker is
    ///      an accounting convenience; the token must trade without it.
    function _trySetShare(address tracker, address user) private {
        try IArgusDividendTracker(tracker).setShare{gas: SHARE_SYNC_GAS}(user, balanceOf(user)) {}
        catch {
            emit ShareSyncFailed(user);
        }
    }

    // - swap-back --

    /// @inheritdoc IArgusTaxToken
    function swapBack() external nonReentrant returns (uint256 proceedsNative18) {
        // No explicit floor on the permissionless path: an unattended keeper has
        // no view on price, so the spot-derived fill floor is its only bound.
        return _swapBack(type(uint256).max, 0);
    }

    /// @notice {swapBack}, with the caller choosing an upper bound on the slice.
    ///
    /// @dev The escape hatch for the one case the automatic cap cannot see.
    ///      `pool.liquidity()` reports IN-RANGE liquidity only, so a third-party
    ///      concentrated position sitting on the current tick makes the pool look
    ///      deeper than it is a few ticks away: the cap sizes a slice against
    ///      liquidity that evaporates mid-swap, the 85% floor catches it, and the
    ///      no-arg form then has no way to respond - it recomputes the same size
    ///      and fails identically forever. That is the same stranded-pot failure
    ///      the liquidity cap was added to remove, arriving by a different route.
    ///      A caller who can see the book picks a slice that clears the floor.
    ///
    ///      A caller-sized swap-back deliberately does NOT move the dynamic
    ///      threshold or the output-per-token EMA. Two reasons, and the second is
    ///      the load-bearing one:
    ///
    ///      1. §6 compares realised output against a reference for a slice WE
    ///         sized. An observation from a slice someone else sized is not a
    ///         measurement of the same thing.
    ///      2. Without it, anyone could churn the controller for the price of
    ///         gas: dust-sized calls return zero proceeds, read as a weak market,
    ///         and walk the threshold wherever the griefer wants inside its
    ///         clamp. The no-arg path is caller-independent, so it is the only
    ///         one allowed to feed the loop.
    /// @param minOutNative18 Caller's own floor on proceeds. Only ever TIGHTENS:
    ///        the spot-derived fill floor below still applies in full, so a sized
    ///        call can never be used to slip past it. Pass 0 to rely on the
    ///        automatic floor alone.
    function swapBack(uint256 maxTokens, uint256 minOutNative18)
        external
        nonReentrant
        returns (uint256 proceedsNative18)
    {
        return _swapBack(maxTokens, minOutNative18);
    }

    function _swapBack(uint256 maxTokens, uint256 minOutNative18) private returns (uint256 proceedsNative18) {
        if (!graduated) revert ArgusErrors.PoolNotSet();

        // The trigger is unchanged by sizing: a sized call is the same
        // swap-back in smaller slices, never a way to sell below the threshold.
        // The value gate lives inside `_sellAccumulated`, which reads the price
        // once and uses that same read for the trigger, the cap and the slippage
        // benchmark. Splitting the read would let the trigger fire on one price
        // and the swap size be computed from another.
        uint256 accumulatedTokens = balanceOf(address(this));

        (uint256 soldTokens, uint256 receivedUsdc6) = _sellAccumulated(accumulatedTokens, maxTokens);

        // No unwrap step: on Arc the pool's USDC payment IS a native credit at
        // 1e12 the size, so proceeds are always an exact 1e12 multiple and go
        // straight back out as `{value:}`.
        proceedsNative18 = receivedUsdc6.toNative18();
        if (proceedsNative18 < minOutNative18) revert ArgusErrors.SlippageFloorBreached();

        uint256 bountyNative18 = (proceedsNative18 * ArgusConstants.SWAPBACK_BOUNTY_BPS) / ArgusConstants.BPS;

        // A caller that cannot receive native forfeits its bounty; it does NOT
        // get to revert the swap-back. Reverting here would let a contract
        // with no `receive` block the only path the tax pot has out, and the
        // bounty exists to make swap-back happen, not to gate it.
        //
        // Safe to call out before the processor: every balance is already
        // settled, `swapBack` is nonReentrant, and the only reachable effect of
        // reentering is sending this contract more native, which then goes to
        // the processor too.
        if (bountyNative18 != 0) {
            (bool ok,) = msg.sender.call{value: bountyNative18}("");
            if (!ok) bountyNative18 = 0;
        }

        // Everything left, not just this swap's proceeds: there is deliberately
        // no sweep function on this contract, so native that arrived any other
        // way would otherwise be stranded here forever.
        IArgusTaxProcessor(taxProcessor).processTax{value: address(this).balance}();

        emit SwappedBack(soldTokens, proceedsNative18, msg.sender, bountyNative18);

        // Dispatch immediately, so the dividend bucket is never left sitting as
        // an unowned prize.
        //
        // Between a swap-back and whoever calls `dispatch()` next, the pending
        // dividend deposit belongs to nobody in particular: anyone can buy just
        // before the dispatch, take a pro-rata share of a deposit they
        // contributed nothing to, and sell straight after. The float that play
