src/ArgusTaxToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {IArgusTaxToken} from "./interfaces/IArgusTaxToken.sol";
import {IArgusTaxProcessor} from "./interfaces/IArgusTaxProcessor.sol";
import {IArgusDividendTracker} from "./interfaces/IArgusDividendTracker.sol";
import {IUniswapV3Pool} from "./interfaces/IUniswapV3.sol";
import {ArgusUnits} from "./libraries/ArgusUnits.sol";
import {TickMath} from "./libraries/TickMath.sol";
import {TaxConfig, ArgusConstants, ArgusErrors} from "./types/ArgusTypes.sol";

/// @notice The one tracker entry point that lives outside {IArgusDividendTracker}.
/// @dev The tracker discovers `mainPool` lazily, by staticcalling back into the
///      token from inside `setShare`. That discovery is the single most expensive
///      share update there is, and it lands on whichever unlucky trade happens to
///      be first. `syncPool()` is permissionless and idempotent, so the token
///      fires it the moment it knows the pool and retires the path. Declared here
///      rather than imported because it is an extension the tracker offers, not
///      part of the contract the token is written against - every call to it is
///      best-effort.
interface IArgusDividendTrackerSync {
    function syncPool() external;
}

/// @notice Everything {ArgusTaxToken-initialize} needs. The Portal builds this.
struct InitParams {
    string name;
    string symbol;
    /// @dev The artwork, surfaced on-chain by {ArgusTaxToken-logo}. May be empty.
    ///      The Portal passes its `TokenMeta.imageURI` straight through; see the
    ///      note on {ArgusTaxToken-logo} for why this one string is stored when the
    ///      other three socials are not.
    string logoURI;
    uint256 totalSupply;
    /// @dev Where the whole supply is minted - the Portal, which sells it down
    ///      the curve and then seeds the graduation LP.
    address supplyRecipient;
    /// @dev The creator. May only ever call `reduceTaxes` and `renounce`; pass
    ///      the zero address to launch already-renounced.
    address owner;
    address portal;
    address taxProcessor;
    /// @dev May be zero only when `config.dividendBps == 0`.
    address dividendTracker;
    /// @dev Addresses the launch flow needs untaxed that the token cannot work
    ///      out for itself - the graduation LP executor and the LP locker. Fixed
    ///      forever here: there is deliberately no setter, so an exemption can
    ///      never be handed out, or revoked, after launch.
    address[] extraExempt;
    TaxConfig config;
}

/// @title ArgusTaxToken
/// @notice A creator-configured tax token that trades on a Uniswap v3 pool.
///
/// @dev Extends OpenZeppelin's {ERC20} DIRECTLY, and that is load-bearing. An
///      earlier token in this codebase (`HigherToken`) inserted itself into a
///      three-deep inheritance chain and its `_update` override became a silent
///      no-op, because `super._update` resolved to the sibling base rather than
///      to ERC20. Nothing reverted; the tax simply never moved. One base, one
///      unambiguous `super`.
///
///      Nothing here is `immutable`. This is an EIP-1167 clone target, and an
///      `immutable` is baked into the IMPLEMENTATION's runtime code, so every
///      clone would silently read the implementation's value - the same tax
///      rate, the same creator wallet, on every launch. All config lives in
///      storage, written once by {initialize}.
///
///      ONE KNOWN AND DELIBERATE DEPARTURE FROM ERC-20, stated here because an
///      integrator reads the contract header and not the middle of `_update`.
///      A sell debits the seller MORE than the amount passed to
///      `transferFrom`:
///
///          transferFrom(from, pool, value)  moves  value * (1 + sellTaxBps/1e4)
///          out of `from`, while spending allowance for `value` only.
///
///      The direction is the surprising part. An ordinary fee-on-transfer token
///      debits `value` and delivers less; this one delivers exactly `value`,
///      because a v3 pool re-reads its own balance and reverts if short by a
///      wei, and takes the tax as a surcharge from what the seller has left.
///      Approve `value * (1 + sellTaxBps/1e4)`, and do not infer the transferred
///      amount from a balance delta.
///
///      Charging the allowance for the surcharge would close the gap and would
///      make an exact-allowance sell revert, which is the honeypot signature the
///      surcharge exists to avoid. The gap is documented rather than moved. See
///      the note at the sell branch in {_update} for the full argument, and
///      audit finding M-1, 2026-09-03.
contract ArgusTaxToken is ERC20, ReentrancyGuard, IArgusTaxToken {
    using ArgusUnits for uint256;

    uint256 private constant Q96 = 1 << 96;

    /// @dev Gas ceiling on each {IArgusDividendTracker-setShare}. Sized against the
    ///      real implementation's measured cost, not a guess: 2.5k on the
    ///      unchanged-share early-out, ~52k median, ~69k for a first-time holder
    ///      (three cold SSTOREs plus the one-off staticcall to {mainPool}), and a
    ///      ~113k one-time path where the tracker first LEARNS the pool address
    ///      and has to un-count a share it had already credited to it. Worst case
    ///      those combine, so the cap has to clear ~182k.
    ///
    ///      Undersizing this is SILENT and permanent: the try/catch swallows the
    ///      out-of-gas, the trade succeeds, and that holder's share is simply
    ///      never recorded - they earn nothing and `totalShares` is wrong from
    ///      then on. {_syncPool} exists to retire the 113k path at launch so the
    ///      combined worst case never actually occurs.
    uint256 private constant SHARE_SYNC_GAS = 200_000;

