    // - initialization --

    /// @notice One-shot setup, called by the factory in the same transaction as
    ///         `Clones.clone()`.
    /// @dev Bundled into a struct rather than taken as eleven arguments because
    ///      the flat form is stack-too-deep on 0.8.24 without via-IR, in the
    ///      compiler's own ABI decoder.
    function initialize(InitParams calldata p) external {
        if (_initialized) revert ArgusErrors.AlreadyInitialized();
        _initialized = true;

        TaxConfig calldata cfg = p.config;
        if (cfg.buyTaxBps > ArgusConstants.MAX_TAX_BPS || cfg.sellTaxBps > ArgusConstants.MAX_TAX_BPS) {
            revert ArgusErrors.TaxTooHigh();
        }
        if (cfg.buyTaxBps + cfg.sellTaxBps == 0) revert ArgusErrors.ZeroTaxNotAllowed();
        if (uint256(cfg.creatorBps) + cfg.burnBps + cfg.dividendBps != ArgusConstants.BPS) {
            revert ArgusErrors.AllocationMustSumTo10000();
        }
        if (cfg.creatorBps > 0 && cfg.creatorWallet == address(0)) {
            revert ArgusErrors.CreatorWalletRequired();
        }
        if (
            p.portal == address(0) || p.taxProcessor == address(0) || p.supplyRecipient == address(0)
                || p.totalSupply == 0
        ) {
            revert ArgusErrors.ZeroAddress();
        }
        // A tracker is optional only when nothing would ever be sent to it.
        if (cfg.dividendBps > 0 && p.dividendTracker == address(0)) revert ArgusErrors.ZeroAddress();

        _tokenName = p.name;
        _tokenSymbol = p.symbol;
        _logoURI = p.logoURI;
        _config = cfg;
        owner = p.owner;
        portal = p.portal;
        taxProcessor = p.taxProcessor;
        dividendTracker = p.dividendTracker;

        launchedAt = block.timestamp;
        if (cfg.taxDuration != 0) taxExpiry = block.timestamp + cfg.taxDuration;

        // The trigger itself is a dollar figure and lives in ArgusConstants. Only
        // the dust guard is supply-relative, so only it needs resolving here.
        minSwapBackTokens = p.totalSupply / ArgusConstants.MIN_SWAPBACK_SUPPLY_DIVISOR;

        isExempt[address(this)] = true;
        isExempt[p.portal] = true;
        isExempt[p.taxProcessor] = true;
        if (p.dividendTracker != address(0)) isExempt[p.dividendTracker] = true;
        isExempt[ArgusConstants.DEAD] = true;
        isExempt[address(0)] = true;
        for (uint256 i; i < p.extraExempt.length; ++i) {
            isExempt[p.extraExempt[i]] = true;
        }

        _mint(p.supplyRecipient, p.totalSupply);
    }

