    // - transfers --

    /// @dev The single ERC20 mutation hook in OZ v5: `_mint`, `_burn`, `transfer`
    ///      and `transferFrom` all land here.
    function _update(address from, address to, uint256 value) internal override {
        if (isExempt[from] || isExempt[to]) {
            // Mint, burn, the graduation LP mint, and every hop between our own
            // contracts. Checked FIRST so the pre-graduation pool block below
            // cannot stop the Portal from seeding the pool at graduation.
            super._update(from, to, value);
        } else if (!graduated) {
            // Phase A: the Portal charges tax in native on the curve, so no
            // token-level tax runs. Only wallet-to-wallet moves are allowed -
            // nobody gets to open a market before graduation does.
            if (from == mainPool || to == mainPool) revert ArgusErrors.PreGraduationPoolTransfer();
            super._update(from, to, value);
        } else {
            (uint16 buyTaxBps, uint16 sellTaxBps) = currentTaxes();

            if (from == mainPool) {
                // BUY. The pool transfers OUT, so skimming here never touches the
                // pool's input-side balance check. Safe with SwapRouter,
                // Universal Router, and every aggregator.
                uint256 taxTokens = (value * buyTaxBps) / ArgusConstants.BPS;
                if (taxTokens != 0) {
                    super._update(from, address(this), taxTokens);
                    super._update(from, to, value - taxTokens);
                } else {
                    super._update(from, to, value);
                }
            } else if (to == mainPool) {
                // SELL (and third-party LP adds, which are indistinguishable and
                // deliberately not special-cased).
                //
                // The pool MUST receive the full `value`: v3 verifies payment by
                // re-reading its own balance inside the swap callback and reverts
                // if it is short by a single wei. Skimming on the way in makes
                // every sell revert - a literal honeypot. So the tax is a
                // SURCHARGE taken from what the seller has left afterwards.
                //
                // The consequence is unavoidable, not a bug: a max-sell pays ZERO
                // sell tax. Proof - let B be the seller's balance and A the amount
                // sold. The pool must receive exactly A, so the total debit is
                // A + A·t. If A == B then A + A·t > B for any t > 0, so either the
                // surcharge is clamped to 0 or the transfer reverts. Reverting on
                // max-sell was explicitly rejected: it is the exact signature
                // honeypot scanners flag, and it would make the token unsellable
                // in the eyes of every terminal. Zero-tax max-sells are the price
                // of being a real, sellable token on v3.
                //
                // The same clamp fires for ANY payer whose balance equals the
                // amount being sold - notably a router that takes custody of the
                // input before paying the pool. See the report notes.
                // THE SURCHARGE IS NOT CHARGED AGAINST THE ALLOWANCE, AND ANY
                // INTEGRATOR HAS TO KNOW THAT. Audit finding M-1, 2026-09-03.
                //
                // The second `_update` below moves tokens out of `from` without
                // passing through `_spendAllowance`, which OZ's `transferFrom`
                // ran once, for `value`, before ever reaching this function. So:
                //
                //     transferFrom(from, to, value) debits `from` by value·(1+t)
                //
                // The unusual half is the DIRECTION. An ordinary fee-on-transfer
                // token debits exactly `value` and DELIVERS LESS than `value`.
                // This one delivers exactly `value` - it has to, the pool counts
                // it - and debits MORE. Anybody who reasons "fee-on-transfer, so
                // the recipient gets less" has it backwards here, and anybody who
                // computes `balanceBefore - balanceAfter` and expects `value`
                // gets a number larger than the one they approved.
                //
                // Two concrete breakages, both real rather than theoretical:
                // a contract that approves exactly `value` and then asserts its
                // own post-balance, and an aggregator that sizes an approval to
                // the trade. Approve `value * (1 + sellTaxBps/10000)`, or approve
                // more.
                //
                // FIXING IT IN THE OBVIOUS WAY WAS CONSIDERED AND REJECTED.
                // Spending the allowance for the surcharge as well would make the
                // token conformant and would make an exact-allowance sell REVERT,
                // which is the same honeypot signature the surcharge design
                // exists to avoid - traded from one place to another, not
                // removed. A token that reverts a normal-approval sell is
                // unsellable in the eyes of every scanner and terminal, whatever
                // the spec says about it. So the conformance gap is documented
                // rather than closed, and this comment is that documentation.
                super._update(from, to, value);

                uint256 surchargeTokens = (value * sellTaxBps) / ArgusConstants.BPS;
                uint256 remaining = balanceOf(from);
                if (surchargeTokens > remaining) surchargeTokens = remaining;
                if (surchargeTokens != 0) super._update(from, address(this), surchargeTokens);
            } else {
                // Wallet to wallet: never taxed.
                super._update(from, to, value);
            }
        }

        // Anti-snipe - a max-wallet cap for the blocks right after graduation -
        // was considered and deliberately declined. Its absence is a decision,
        // not an oversight; do not re-add it without one. The tradeoff it leaves
        // standing: nothing here prevents a single wallet taking a large share of
        // supply in the opening blocks.

        // NO swap-back here. Ever. On v3 this code runs INSIDE `pool.swap()`
        // with the pool's own reentrancy lock held, so swapping through that pool
        // from here always reverts. Swap-back is its own transaction.
        _syncShares(from, to);
    }

    /// @dev Push both sides' post-transfer balances to the dividend tracker.
    ///      Pools and exempt addresses are skipped: they earn nothing, so telling
    ///      the tracker about them is pure gas.
    function _syncShares(address from, address to) private {
        address tracker = dividendTracker;
        if (tracker == address(0)) return;
        if (!isExempt[from] && from != mainPool) _trySetShare(tracker, from);
        if (!isExempt[to] && to != mainPool) _trySetShare(tracker, to);
    }

    /// @dev try/catch plus a gas cap, and both halves matter.
    ///
    ///      This call happens inside `pool.swap()` on every buy and every sell.
    ///      If the tracker reverts - a bug, an unbounded loop, an out-of-gas -
    ///      an unguarded call would revert the trade, and a token whose trades
    ///      revert is a honeypot no matter how honest the intent. The tracker is
    ///      an accounting convenience; the token must trade without it.
    function _trySetShare(address tracker, address user) private {
        try IArgusDividendTracker(tracker).setShare{gas: SHARE_SYNC_GAS}(user, balanceOf(user)) {}
        catch {
            emit ShareSyncFailed(user);
        }
    }

    // - swap-back --

    /// @inheritdoc IArgusTaxToken
    function swapBack() external nonReentrant returns (uint256 proceedsNative18) {
        // No explicit floor on the permissionless path: an unattended keeper has
        // no view on price, so the spot-derived fill floor is its only bound.
        return _swapBack(type(uint256).max, 0);
    }

    /// @notice {swapBack}, with the caller choosing an upper bound on the slice.
    ///
    /// @dev The escape hatch for the one case the automatic cap cannot see.
    ///      `pool.liquidity()` reports IN-RANGE liquidity only, so a third-party
    ///      concentrated position sitting on the current tick makes the pool look
    ///      deeper than it is a few ticks away: the cap sizes a slice against
    ///      liquidity that evaporates mid-swap, the 85% floor catches it, and the
    ///      no-arg form then has no way to respond - it recomputes the same size
    ///      and fails identically forever. That is the same stranded-pot failure
    ///      the liquidity cap was added to remove, arriving by a different route.
    ///      A caller who can see the book picks a slice that clears the floor.
    ///
    ///      A caller-sized swap-back deliberately does NOT move the dynamic
    ///      threshold or the output-per-token EMA. Two reasons, and the second is
    ///      the load-bearing one:
    ///
    ///      1. §6 compares realised output against a reference for a slice WE
    ///         sized. An observation from a slice someone else sized is not a
    ///         measurement of the same thing.
    ///      2. Without it, anyone could churn the controller for the price of
    ///         gas: dust-sized calls return zero proceeds, read as a weak market,
    ///         and walk the threshold wherever the griefer wants inside its
    ///         clamp. The no-arg path is caller-independent, so it is the only
    ///         one allowed to feed the loop.
    /// @param minOutNative18 Caller's own floor on proceeds. Only ever TIGHTENS:
    ///        the spot-derived fill floor below still applies in full, so a sized
    ///        call can never be used to slip past it. Pass 0 to rely on the
    ///        automatic floor alone.
    function swapBack(uint256 maxTokens, uint256 minOutNative18)
        external
        nonReentrant
        returns (uint256 proceedsNative18)
    {
        return _swapBack(maxTokens, minOutNative18);
    }

    function _swapBack(uint256 maxTokens, uint256 minOutNative18) private returns (uint256 proceedsNative18) {
        if (!graduated) revert ArgusErrors.PoolNotSet();

        // The trigger is unchanged by sizing: a sized call is the same
        // swap-back in smaller slices, never a way to sell below the threshold.
        // The value gate lives inside `_sellAccumulated`, which reads the price
        // once and uses that same read for the trigger, the cap and the slippage
        // benchmark. Splitting the read would let the trigger fire on one price
        // and the swap size be computed from another.
        uint256 accumulatedTokens = balanceOf(address(this));

        (uint256 soldTokens, uint256 receivedUsdc6) = _sellAccumulated(accumulatedTokens, maxTokens);

        // No unwrap step: on Arc the pool's USDC payment IS a native credit at
        // 1e12 the size, so proceeds are always an exact 1e12 multiple and go
        // straight back out as `{value:}`.
        proceedsNative18 = receivedUsdc6.toNative18();
        if (proceedsNative18 < minOutNative18) revert ArgusErrors.SlippageFloorBreached();

        uint256 bountyNative18 = (proceedsNative18 * ArgusConstants.SWAPBACK_BOUNTY_BPS) / ArgusConstants.BPS;

        // A caller that cannot receive native forfeits its bounty; it does NOT
        // get to revert the swap-back. Reverting here would let a contract
        // with no `receive` block the only path the tax pot has out, and the
        // bounty exists to make swap-back happen, not to gate it.
        //
        // Safe to call out before the processor: every balance is already
        // settled, `swapBack` is nonReentrant, and the only reachable effect of
        // reentering is sending this contract more native, which then goes to
        // the processor too.
        if (bountyNative18 != 0) {
            (bool ok,) = msg.sender.call{value: bountyNative18}("");
            if (!ok) bountyNative18 = 0;
        }

        // Everything left, not just this swap's proceeds: there is deliberately
        // no sweep function on this contract, so native that arrived any other
        // way would otherwise be stranded here forever.
        IArgusTaxProcessor(taxProcessor).processTax{value: address(this).balance}();

        emit SwappedBack(soldTokens, proceedsNative18, msg.sender, bountyNative18);

        // Dispatch immediately, so the dividend bucket is never left sitting as
        // an unowned prize.
        //
        // Between a swap-back and whoever calls `dispatch()` next, the pending
        // dividend deposit belongs to nobody in particular: anyone can buy just
        // before the dispatch, take a pro-rata share of a deposit they
        // contributed nothing to, and sell straight after. The float that play
        // needs is proportional to the undispatched pot, so the incentive grows
        // the longer nobody calls it. Dispatching here caps the prize at a single
        // swap-back of accrual - about $10 at the trigger - which is not worth
        // anyone's float.
        //
        // try/catch is mandatory, not defensive. `dispatch` pushes to a creator
        // wallet and swaps the burn bucket through the pool, and any of those
        // failing must not revert the swap-back: that would let a griefer seal
        // the tax pot's only exit by making one destination fail. The processor
        // parks failures internally for exactly this reason; this is the same
        // guarantee one level up.
        try IArgusTaxProcessor(taxProcessor).dispatch() {}
        catch {
            emit DispatchFailed();
        }
    }

    /// @dev The swap half of {swapBack}, split out only because the whole thing
    ///      in one frame is stack-too-deep on 0.8.24 without via-IR.
    function _sellAccumulated(uint256 accumulatedTokens, uint256 maxTokens)
        private
        returns (uint256 soldTokens, uint256 receivedUsdc6)
    {
        address pool = mainPool;
        bool tokenIs0 = tokenIsToken0;

        uint256 sellTokens;
        uint256 expectedUsdc6;
        {
            (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(pool).slot0();

            // The trigger, in tokens at this instant's price. Same helper the
            // public {swapBackThreshold} view calls, so the number a keeper
            // reads and the number enforced here cannot disagree by a rounding
            // step and hand it an unexplainable revert.
            if (accumulatedTokens < _thresholdTokens(sqrtPriceX96, tokenIs0)) {
                revert ArgusErrors.BelowSwapBackThreshold();
            }

            uint128 poolLiquidity = IUniswapV3Pool(pool).liquidity();

            // Sell `min(accumulated, safeCap)` rather than all-or-nothing.
            //
            // The cap is now the ONLY price-impact control in the contract - the
            // §6 threshold controller that used to share the job is gone - so it
            // carries more weight than it did, not less. Sizing each slice
            // against the pool's actual in-range liquidity means that as the pool
            // thins the slices shrink with it, and the pot still drains, just
            // over more calls.
            //
            // Limitation worth naming: `liquidity()` is IN-RANGE liquidity only.
            // A third-party concentrated position sitting on the current tick can
            // make the cap look generous relative to what is available just past
            // the tick boundary, and the 85% guard can still trip there. The cap
            // makes that unlikely and self-scaling; it does not make it
            // impossible. {swapBack(uint256)} is the answer to the residue: a
            // caller who can see the book picks the slice this cap cannot.
            uint256 capTokens = _safeSellCap(sqrtPriceX96, poolLiquidity, tokenIs0);
            sellTokens = accumulatedTokens < capTokens ? accumulatedTokens : capTokens;
            if (maxTokens < sellTokens) sellTokens = maxTokens;
            if (sellTokens == 0) revert ArgusErrors.NothingToSwapBack();

            expectedUsdc6 = _spotQuoteUsdc6(sellTokens, sqrtPriceX96, tokenIs0);
        }

        // Selling the token: zeroForOne when the token is token0. The price bound
        // is the extreme tick, so the swap is limited by size, not by price - the
        // 85% floor below is what actually protects it.
        uint160 limitX96 = tokenIs0 ? TickMath.MIN_SQRT_RATIO + 1 : TickMath.MAX_SQRT_RATIO - 1;

        _expectedPoolCallback = pool;
        // casting to 'int256' is safe because sellTokens is capped at
        // balanceOf(address(this)), which can never exceed totalSupply.
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 amountSpecified = int256(sellTokens);
        (int256 amount0, int256 amount1) =
            IUniswapV3Pool(pool).swap(address(this), tokenIs0, amountSpecified, limitX96, "");
        _expectedPoolCallback = address(0);

        // Read what the pool actually took, not what we asked it to take. A
        // partial fill would otherwise feed a wrong output-per-token observation
        // into the EMA and move the threshold on bad data.
        soldTokens = uint256(tokenIs0 ? amount0 : amount1);
        if (soldTokens != sellTokens) revert ArgusErrors.SlippageFloorBreached();

        {
            // Negating the output delta before checking its sign would turn a
            // (nonsensical) positive into a balance-sized uint, and the only
            // thing catching it downstream would be an arithmetic overflow.
            int256 outDelta = tokenIs0 ? amount1 : amount0;
            if (outDelta >= 0) revert ArgusErrors.SlippageFloorBreached();
            // forge-lint: disable-next-line(unsafe-typecast)
            receivedUsdc6 = uint256(-outDelta);
        }
        if (receivedUsdc6 * ArgusConstants.BPS < expectedUsdc6 * ArgusConstants.SLIPPAGE_FLOOR_BPS) {
            revert ArgusErrors.SlippageFloorBreached();
        }
    }

    /// @dev Pays the pool for the swap it is mid-way through.
    ///
    ///      Paying from inside the callback, against a pool this contract called
    ///      directly, is a requirement and not a style choice. Arc enforces a
    ///      blocklist at runtime, and the two USDC entry points are not
    ///      symmetric: `0x3600`'s `transfer` does NOT consult it, while
    ///      `transferFrom` DOES, and it checks the SPENDER. Routing swap-back
    ///      through approve + SwapRouter02 instead would put this token contract
    ///      under a blocklist check on every single swap-back. The direct
    ///      `pool.swap()` keeps both legs on `transfer`: the pool pays us by
    ///      `transfer`, and we pay it with a plain internal balance move.
    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata) external {
        if (msg.sender != _expectedPoolCallback || _expectedPoolCallback == address(0)) {
            revert ArgusErrors.UnexpectedCallback();
        }
        // Only ever one positive delta, and it is always this token: `swapBack`
        // is the only caller and it only ever sells. Rejecting a non-positive
        // delta is not paranoia about Uniswap - it stops a two-sided-zero swap
        // from casting a negative int256 into a balance-sized uint256.
        int256 owedDelta = amount0Delta > 0 ? amount0Delta : amount1Delta;
        if (owedDelta <= 0) revert ArgusErrors.UnexpectedCallback();
        // forge-lint: disable-next-line(unsafe-typecast)
        uint256 owedTokens = uint256(owedDelta);

        // Raw move, never the taxed path: the pool is about to re-read its own
        // balance and demand exactly `owedTokens`. `address(this)` is exempt so
        // {_update} would take the same branch anyway, but going straight to
        // ERC20 makes it impossible for a future edit to a tax branch to skim
        // this transfer by accident.
        super._update(address(this), msg.sender, owedTokens);
    }

    /// @dev Largest input that keeps this swap's price impact inside
    ///      {ArgusConstants-MAX_PRICE_IMPACT_BPS}, where the derivation lives. Both
    ///      branches reduce to the same thing: a fixed fraction of the pool's
    ///      in-range virtual reserve of THIS token.
    ///
    ///      The constant is shared with {ArgusTaxProcessor-executeBurn}, which caps
    ///      the same way in the opposite direction. Read it from ArgusConstants, do
    ///      not re-declare it here: the two paths guard the same pool against the
    ///      same failure, and a local copy is how they drift apart.
    function _safeSellCap(uint160 sqrtPriceX96, uint128 poolLiquidity, bool tokenIs0)
        private
        pure
        returns (uint256)
    {
        if (poolLiquidity == 0 || sqrtPriceX96 == 0) return 0;
        uint256 budget = (uint256(poolLiquidity) * ArgusConstants.MAX_PRICE_IMPACT_BPS) / ArgusConstants.BPS;
        // token0 reserve is L/sqrtP, token1 reserve is L·sqrtP.
        return tokenIs0 ? Math.mulDiv(budget, Q96, sqrtPriceX96) : Math.mulDiv(budget, sqrtPriceX96, Q96);
    }

    /// @dev Zero-impact, zero-fee output at the pool's current price - the
    ///      benchmark the 85% floor is measured against.
    ///
    ///      Note what that floor can and cannot see. `slot0` is read in this same
    ///      call, so the front-run leg of a sandwich has already moved the price
    ///      by the time we quote and is invisible here. What the floor catches is
    ///      the size of our own execution gap: a swap that returns far less than
    ///      the pool's own posted price means the book in front of us is thin or
    ///      poisoned, and the bot should come back later. That is the protection
    ///      that is actually available to a victim quoting from inside the pool.
    function _spotQuoteUsdc6(uint256 amountTokens, uint160 sqrtPriceX96, bool tokenIs0)
        private
        pure
        returns (uint256)
    {
        if (tokenIs0) {
            // out(token1) = in · (sqrtP/2^96)^2
            return Math.mulDiv(Math.mulDiv(amountTokens, sqrtPriceX96, Q96), sqrtPriceX96, Q96);
        }
        // out(token0) = in / (sqrtP/2^96)^2
        return Math.mulDiv(Math.mulDiv(amountTokens, Q96, sqrtPriceX96), Q96, sqrtPriceX96);
    }

    /// @dev How many tokens are currently worth
    ///      {ArgusConstants-MIN_SWAPBACK_VALUE_USDC6}, floored by the dust
    ///      guard. The inverse of {_spotQuoteUsdc6}: value / price rather than
    ///      amount * price, which is why the branches are the mirror image.
    ///
    ///      There used to be a §6 controller here instead - a bidirectional
    ///      threshold nudged 1% per swap-back against an EMA of realised
    ///      output-per-token, meant to make sells bigger and rarer in weak
    ///      markets. It is gone, and not merely as redundant machinery: its input
    ///      was actively wrong. Output-per-token is dominated by PRICE LEVEL, not
    ///      by depth, so a token whose price doubled produced "better output" and
    ///      the controller read that as a strong market. It was integrating price
    ///      drift and reporting it as market health.
    ///
    ///      A quote-denominated trigger absorbs that drift directly and correctly:
    ///      in a weak market the same tax accrual is worth less, so it simply
    ///      takes longer to reach $10 and sells become rarer on their own, with
    ///      no feedback loop, no lag, and no clamp to drift into. Price impact is
    ///      handled by {_safeSellCap}, which measures liquidity - the quantity
    ///      that actually determines impact - instead of inferring it from a
    ///      noisy price signal. Do not reintroduce the controller.
    function _thresholdTokens(uint160 sqrtPriceX96, bool tokenIs0) private view returns (uint256) {
        uint256 floorTokens = minSwapBackTokens;
        if (sqrtPriceX96 == 0) return type(uint256).max;

        uint256 valueUsdc6 = ArgusConstants.MIN_SWAPBACK_VALUE_USDC6;
        uint256 tokens = tokenIs0
            // value is token1, so tokens = value / (sqrtP/2^96)^2
            ? Math.mulDiv(Math.mulDiv(valueUsdc6, Q96, sqrtPriceX96), Q96, sqrtPriceX96)
            // value is token0, so tokens = value * (sqrtP/2^96)^2
            : Math.mulDiv(Math.mulDiv(valueUsdc6, sqrtPriceX96, Q96), sqrtPriceX96, Q96);

        return tokens < floorTokens ? floorTokens : tokens;
    }

    /// @inheritdoc IArgusTaxToken
    function swapBackThreshold() external view returns (uint256) {
        address pool = mainPool;
        // Sentinel rather than a revert: a batch reader sweeping every Argus token
        // must not blow up on one that has not graduated.
        if (pool == address(0)) return type(uint256).max;
        (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(pool).slot0();
        return _thresholdTokens(sqrtPriceX96, tokenIsToken0);
    }

    // - owner functions (there are exactly two) --

    /// @inheritdoc IArgusTaxToken
    /// @dev Down-only, and zero is a legal destination: turning the tax off early
    ///      is the same promise as letting it expire. `buyTaxBps + sellTaxBps > 0`
    ///      is an initialize-time check about picking the right launch mode, not
    ///      a floor the creator is trapped above.
    function reduceTaxes(uint16 newBuyBps, uint16 newSellBps) external {
        if (msg.sender != owner) revert ArgusErrors.OnlyOwner();
        TaxConfig storage cfg = _config;
        if (newBuyBps > cfg.buyTaxBps || newSellBps > cfg.sellTaxBps) {
            revert ArgusErrors.TaxesNotDownOnly();
        }
        cfg.buyTaxBps = newBuyBps;
        cfg.sellTaxBps = newSellBps;
        emit TaxesReduced(newBuyBps, newSellBps);
    }

    /// @inheritdoc IArgusTaxToken
    function renounce() external {
        if (msg.sender != owner) revert ArgusErrors.OnlyOwner();
        emit OwnershipRenounced(owner);
        owner = address(0);
    }

    // - views --

    /// @inheritdoc IArgusTaxToken
    function accumulatedTax() external view returns (uint256) {
        return balanceOf(address(this));
    }

    /// @inheritdoc IArgusTaxToken
    function config() external view returns (TaxConfig memory) {
        return _config;
    }

    /// @inheritdoc IArgusTaxToken
    function currentTaxes() public view returns (uint16 buyTaxBps, uint16 sellTaxBps) {
        if (taxExpiry != 0 && block.timestamp >= taxExpiry) return (0, 0);
        return (_config.buyTaxBps, _config.sellTaxBps);
    }

    /// @dev Native arrives here two ways, and neither is a normal payment: the
    ///      pool's USDC payout during {swapBack} (Arc mirrors every `0x3600`
    ///      transfer onto the native balance), and anything anyone chooses to
    ///      send. Both are forwarded to the processor by the next swap-back -
    ///      there is no sweep function and no way for the owner to touch it.
    receive() external payable {}
}

