// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @dev Minimal Uniswap V3 interfaces - only the functions PotatoPad touches.
///      Hand-written so the project compiles standalone on 0.8.24 without
///      pulling in the 0.7.x Uniswap solidity packages.

interface IUniswapV3Factory {
    function getPool(address tokenA, address tokenB, uint24 fee) external view returns (address pool);

    function createPool(address tokenA, address tokenB, uint24 fee) external returns (address pool);

    function feeAmountTickSpacing(uint24 fee) external view returns (int24);

    /// @dev NOT renounced on Arc mainnet (owner `0x33f26c5d...`). Whoever holds
    ///      it can call `setFeeProtocol` and divert up to 25% of swap fees, which
    ///      are creator and treasury revenue. Read it, surface it, do not assume
    ///      it is the zero address.
    function owner() external view returns (address);
}

interface IUniswapV3Pool {
    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );

    function liquidity() external view returns (uint128);

    /// @dev Added for The Argus: `swapBack()` has to know which side of the pair
    ///      it is selling before it can pick a `sqrtPriceLimitX96` bound or read
    ///      the callback deltas the right way round.
    function token0() external view returns (address);

    function token1() external view returns (address);

    function fee() external view returns (uint24);

    function tickSpacing() external view returns (int24);

    /// @dev Cumulative fees earned per unit of liquidity across ALL of the pool's
    ///      history, in Q128.128. Grows on every swap and is never reset - which
    ///      is what lets {PotatoRewardToken} account for fees continuously,
    ///      without waiting for anyone to call `collect`.
    function feeGrowthGlobal0X128() external view returns (uint256);

    function feeGrowthGlobal1X128() external view returns (uint256);

    /// @dev Per-tick fee growth on the far side of `tick` from the current price.
    ///      Needed to subtract the out-of-range portion when deriving how much a
    ///      bounded position has earned.
    function ticks(int24 tick)
        external
        view
        returns (
            uint128 liquidityGross,
            int128 liquidityNet,
            uint256 feeGrowthOutside0X128,
            uint256 feeGrowthOutside1X128,
            int56 tickCumulativeOutside,
            uint160 secondsPerLiquidityOutsideX128,
            uint32 secondsOutside,
            bool initialized
        );

    function initialize(uint160 sqrtPriceX96) external;

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    struct CollectParams {
        uint256 tokenId;
        address recipient;
        uint128 amount0Max;
        uint128 amount1Max;
    }

    struct DecreaseLiquidityParams {
        uint256 tokenId;
        uint128 liquidity;
        uint256 amount0Min;
        uint256 amount1Min;
        uint256 deadline;
    }

    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);

    function collect(CollectParams calldata params)
        external
        payable
        returns (uint256 amount0, uint256 amount1);

    /// @dev Removes liquidity from a position (owner/approved only); the freed
    ///      principal is added to the position's owed balance, harvested via {collect}.
    function decreaseLiquidity(DecreaseLiquidityParams calldata params)
        external
        payable
        returns (uint256 amount0, uint256 amount1);

    function positions(uint256 tokenId)
        external
        view
        returns (
            uint96 nonce,
            address operator,
            address token0,
            address token1,
            uint24 fee,
            int24 tickLower,
            int24 tickUpper,
            uint128 liquidity,
            uint256 feeGrowthInside0LastX128,
            uint256 feeGrowthInside1LastX128,
            uint128 tokensOwed0,
            uint128 tokensOwed1
        );

    function ownerOf(uint256 tokenId) external view returns (address owner);

    function safeTransferFrom(address from, address to, uint256 tokenId) external;
}

interface IWETH9 {
    function deposit() external payable;

    function withdraw(uint256 amount) external;

    function transfer(address to, uint256 amount) external returns (bool);

    function approve(address spender, uint256 amount) external returns (bool);

    function balanceOf(address account) external view returns (uint256);
}

src/interfaces/IArgusTaxToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {TaxConfig} from "../types/ArgusTypes.sol";

/// @title IArgusTaxToken
/// @notice A launch token whose trades are taxed, on a Uniswap v3 pool.
interface IArgusTaxToken {
    event SwappedBack(uint256 soldTokens, uint256 proceedsNative18, address indexed caller, uint256 bounty);
    event TaxesReduced(uint16 buyTaxBps, uint16 sellTaxBps);
    event MainPoolSet(address indexed pool);

    /// @notice Swap the accumulated tax tokens for native USDC and forward them
    ///         to the processor, minus a caller bounty.
    ///
    /// @dev Deliberately a SEPARATE TRANSACTION, never reachable from
    ///      `_transfer`. On a v3 pool a taxed transfer runs *inside*
    ///      `pool.swap()` while the pool's reentrancy lock is held, so any
    ///      attempt to swap through that same pool from a transfer hook reverts.
    ///      This is the single hardest constraint in the design.
    ///
    ///      Sells ONLY the tax accumulator held at `balanceOf(address(this))`.
    ///      The graduation LP position is locked in the locker and is never
    ///      touched by anything here.
    function swapBack() external returns (uint256 proceedsNative18);

    /// @notice Tokens currently waiting to be swapped back.
    function accumulatedTax() external view returns (uint256);

    /// @notice The amount of accumulated tax, in TOKENS, that triggers a
    ///         swap-back right now.
    ///
    /// @dev DERIVED FROM THE POOL PRICE, not stored. The real rule is a quote
    ///      value - swapBack once the pot is worth
    ///      {ArgusConstants-MIN_SWAPBACK_VALUE_USDC6} - and this converts that
    ///      into tokens at the current price, floored by the token sanity floor.
    ///
    ///      Two consequences for anything reading it:
    ///
    ///      1. It MOVES EVERY BLOCK, because the price does. Comparing
    ///         `accumulatedTax()` against a fresh read is correct; caching it is
    ///         not. It used to be a storage slot, so a bot that cached it was
    ///         previously fine and now is not.
    ///      2. It returns `type(uint256).max` when no pool is registered, rather
    ///         than reverting, so batch readers do not blow up on a token that
    ///         has not graduated.
    function swapBackThreshold() external view returns (uint256);

    /// @notice Down-only. Reverts if either argument exceeds the current value.
    function reduceTaxes(uint16 newBuyBps, uint16 newSellBps) external;

    /// @notice Burn ownership. There is no other owner function besides
    ///         {reduceTaxes}: no pause, no blacklist, no mint, no wallet change.
    function renounce() external;

    function config() external view returns (TaxConfig memory);

    /// @notice Effective rates right now: both read 0 once the tax has expired.
    function currentTaxes() external view returns (uint16 buyTaxBps, uint16 sellTaxBps);

    function mainPool() external view returns (address);

    function taxProcessor() external view returns (address);

    function dividendTracker() external view returns (address);
}

src/interfaces/IArgusTaxProcessor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @title IArgusTaxProcessor
/// @notice Splits tax income into four buckets and pushes them out. One clone
///         per launch. All amounts are native USDC (18dp).
///
/// @dev Money arrives from two places and ends up in the same buckets either
///      way: from the Portal while the token is on the curve (already native, no
///      swap-back needed) and from the token itself after graduation (proceeds
///      of {IArgusTaxToken-swapBack}).
///
///      Splitting happens at RECEIPT; paying out happens later in {dispatch},
///      which is permissionless. That separation is what lets a failing
///      destination be parked instead of blocking the other three.
interface IArgusTaxProcessor {
    event TaxReceived(address indexed from, uint256 amountNative18, uint256 feeNative18);
    event Dispatched(uint256 creator, uint256 burn, uint256 dividend, uint256 treasury);
    /// @notice A push FAILED and the amount was parked for {claim} instead.
    /// @dev Still means what it always meant: something went wrong at a
    ///      destination. Monitoring should keep treating it as a soft failure.
    event PayoutParked(address indexed to, uint256 amountNative18);

    /// @notice The creator's slice was credited to {claimable} - the normal,
    ///         successful outcome of every dispatch on a claim-based launch.
    /// @dev A SEPARATE EVENT from {PayoutParked}, and the separation is the whole
    ///      point. Both end with money in `claimable`, but one is a fault and the
    ///      other is the happy path, and a monitor cannot tell them apart from
    ///      the state alone. Reusing PayoutParked here would have made every
    ///      healthy dispatch on every new launch raise a payout-failure alert
    ///      forever - which is exactly what the keeper's watcher did with it.
    event CreatorFeeAccrued(address indexed creator, uint256 amountNative18, uint256 totalClaimableNow);

    /// @notice Post-graduation inflow, from the token's `swapBack()`.
    function processTax() external payable;

    /// @notice Pre-graduation inflow, from the Portal, charged in native at
    ///         trade time. (Wired in milestone 3; the entry point exists now so
    ///         the processor never needs a second version.)
    function processBondingCurveTax() external payable;

    /// @notice Push every non-empty bucket to its destination. Anyone may call.
    /// @dev NEVER REVERTS, for any reason. Safe to call blind, on a loop, by a
    ///      keeper that has not read `buckets()` first.
    ///
    ///      Stating only the narrow half of this - "never reverts because a
    ///      destination failed" - is what the docstring used to say, and it
    ///      invites exactly the wrong inference: that it may revert for some
    ///      OTHER reason. It did once, on empty buckets, and that cost three
    ///      agents a round of work when the token began dispatching at the end
    ///      of `swapBack` and empty became the normal state a keeper finds.
    ///
    ///      Two guarantees, both load-bearing for an integrator: a failing
    ///      destination parks and the others still get paid, and an empty call
    ///      is a silent no-op rather than a failed transaction in your history.
    ///
    ///      THE CREATOR IS NOT PAID BY THIS CALL. Their slice is credited to
    ///      `claimable[creatorWallet]` and stays there until somebody calls
    ///      {claim}; every other destination is still pushed. An integrator
    ///      reading a creator's balance after a dispatch and finding it unchanged
    ///      is looking in the wrong place - read `claimable(creatorWallet)`.
    ///
    ///      Older launches PUSH instead, and their processors are immutable, so
    ///      both behaviours exist on chain permanently. Tell them apart by
    ///      reading `claimable(creatorWallet)`: a claim-based launch accrues
    ///      there, a push-based one never does.
    function dispatch() external;

    function buckets()
        external
        view
        returns (uint256 creator, uint256 burn, uint256 dividend, uint256 treasury);

    /// @notice Parked payouts, withdrawable by their owner after a failed push.
    function claimable(address account) external view returns (uint256);
}

src/interfaces/IArgusDividendTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @title IArgusDividendTracker
/// @notice Pro-rata native-USDC dividends with no staking and no opt-in: holding
///         is enough. One clone per launch.
///
/// @dev Accounting is an accumulated-per-share checkpoint (`accPerShareX128`), so
///      every operation is O(1) and there is no holder loop to run out of gas and
///      no cap on holder count. You earn only for deposits that land while you
///      hold - buying immediately before a deposit earns nothing, so the obvious
///      snipe has no target.
///
///      Two invariants that are easy to get wrong and silent when you do:
///
///      1. {setShare} MUST settle against the tracker's OWN stored share for the
///         user, never against the `balance` argument. Settling against the new
///         balance retroactively reprices the window that just closed.
///      2. A payout that fails MUST credit back to pending and MUST NOT revert.
///         On Arc this is mandatory rather than defensive: the chain enforces a
///         blocklist at runtime, so a native send to a blocklisted holder reverts
///         inside the EVM and would otherwise brick an entire batch.
interface IArgusDividendTracker {
    event ShareUpdated(address indexed user, uint256 oldShare, uint256 newShare);
    event Deposited(uint256 amountNative18, uint256 accPerShareX128);
    event Claimed(address indexed user, address indexed caller, uint256 amountNative18);
    event ClaimFailed(address indexed user, uint256 amountNative18);

    /// @notice Called by the token on both sides of every transfer.
    /// @dev MUST tolerate being called inside a Uniswap swap. If this reverts,
    ///      every trade reverts and the token is a honeypot - so the token side
    ///      gas-caps and try/catches it, and this side must not assume it will.
    function setShare(address user, uint256 balance) external;

    /// @notice Fund the pool of claimable dividends. Native USDC (18dp).
    /// @dev When totalShares == 0 the deposit is HELD, not distributed: the
    ///      checkpoint must not advance, or the value is silently burnt instead
    ///      of banked for whoever holds next.
    function deposit() external payable;

    function withdrawableDividendOf(address user) external view returns (uint256 amountNative18);

    function withdrawDividends() external returns (uint256 amountNative18);

    /// @notice Claim on someone else's behalf. Caller pays gas, holder gets paid.
    /// @dev This is the entire mechanism behind "rewards are automatic" - and it
    ///      is permissionless, so if our bot dies anyone can keep paying holders.
    function withdrawDividendsFor(address user) external returns (uint256 amountNative18);

    /// @notice Batch form of {withdrawDividendsFor}. Bounded loop; skips zeros.
    function distributeDividend(address[] calldata users)
        external
        returns (uint256 paidNative18, uint256 skipped);

    /// @notice Full-gas pull for one holder. Permissionless: the caller pays the
    ///         gas, `user` receives the dividends.
    /// @dev Listed here because the four functions above are ALL stipend-capped,
    ///      and an integrator reading only those concludes that a contract holder
    ///      whose `receive()` costs more than 30k can never be paid. It can: this
    ///      is the path that pays it, and it is the reason the cap on the others
    ///      is safe to keep. Reverts rather than parking, so a caller who asked
    ///      for one payout is told when it failed.
    function claim(address user) external returns (uint256 amountNative18);

    /// @notice Send YOUR OWN settled dividends to an address you nominate.
    /// @dev Callable only by the holder the dividends belong to, and it moves
    ///      only value already settled to that holder - it cannot redirect anyone
    ///      else's, and it cannot change where future dividends accrue. The exit
    ///      for a holder that can SIGN but cannot RECEIVE, which on Arc means one
    ///      caught by the node-level blocklist on native transfers. Repeatable,
    ///      not a one-time reassignment.
    function claimTo(address destination) external returns (uint256 amountNative18);

    /// @notice Release a banked deposit to the current shareholders without
    ///         waiting for another deposit to arrive.
    /// @dev A deposit that lands with nobody eligible is BANKED, and the bank is
    ///      released only once enough of the supply is in eligible hands or the
    ///      hold window has lapsed. Both of those used to be evaluated solely on
    ///      the arrival of a further deposit, which made the bank conditionally
    ///      unreachable. Permissionless, pays the caller nothing beyond its own
    ///      pro-rata share, and reverts when there is nothing banked, nobody
    ///      eligible, or the release conditions are not yet met.
    function flushBank() external returns (uint256 releasedNative18);

    /// @notice Recover dividends owed to a CONTRACT that can neither receive
    ///         native nor call anything - a secondary pool, an escrow, a
    ///         receiverless vault.
    /// @dev Two-phase and permissionless. Each call attempts a full-gas payout to
    ///      `user`: if that succeeds the holder is simply paid and nothing is
    ///      reclaimed. Only a holder that fails that attempt TWICE, a grace window
    ///      apart, has its settled dividends folded back into the accumulator for
    ///      the remaining shareholders and is removed from the denominator so it
    ///      cannot strand more. Never callable against an EOA - an EOA can sign
    ///      {claimTo} - and it moves nothing to the caller.
    function reclaimStranded(address user)
        external
        returns (uint256 paidNative18, uint256 redistributedNative18);

    function totalShares() external view returns (uint256);

    function shareOf(address user) external view returns (uint256);

    function isExcluded(address account) external view returns (bool);
}

